// Worker entry point (wrangler.jsonc "main"): the OpenNext app for HTTP requests,
// plus the daily cron (wrangler.jsonc "triggers") for backups and log retention.
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.

// The build output may not exist yet (CI type-checks before building), hence ts-ignore.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { runMaintenance, type MaintenanceEnv } from "./lib/maintenance";
// Tà tưa: the Petdex game runs inside one SQLite-backed Durable Object (petdex/server/durable.js).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: plain JavaScript module
export { PetdexPark } from "./petdex/server/durable.js";

// Durable Object classes the OpenNext build may define; re-exported so bindings keep working.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

interface ScheduledContext {
  waitUntil(promise: Promise<unknown>): void;
}

interface GameEnv {
  PETDEX?: { idFromName(name: string): unknown; get(id: unknown): { fetch(request: Request): Promise<Response> } };
}

/** The game's API and park WebSocket live under /ta-tua; everything else is the Next.js app. */
function gameRequest(request: Request, env: GameEnv): Promise<Response> | null {
  const url = new URL(request.url);
  const isApi = url.pathname === "/ta-tua/api" || url.pathname.startsWith("/ta-tua/api/");
  if (!isApi && url.pathname !== "/ta-tua/ws") return null;
  if (!env.PETDEX) return Promise.resolve(Response.json({ error: "Tà tưa chưa được bật trên máy chủ này." }, { status: 503 }));
  url.pathname = isApi ? url.pathname.replace(/^\/ta-tua/, "") : "/ws";
  const stub = env.PETDEX.get(env.PETDEX.idFromName("park"));
  return stub.fetch(new Request(url, request));
}

const worker = {
  fetch(request: Request, env: MaintenanceEnv & GameEnv, ctx: ScheduledContext) {
    return gameRequest(request, env) ?? handler.fetch(request, env, ctx);
  },
  async scheduled(_controller: unknown, env: MaintenanceEnv, ctx: ScheduledContext) {
    ctx.waitUntil(runMaintenance(env));
  },
};

export default worker;
